  o=P.veil;gl.useProgram(o.p);gl.uniformMatrix4fv(o.u.uVP,false,VPM);gl.uniformMatrix4fv(o.u.uView,false,VWM);gl.uniform3fv(o.u.uEye,eyeL);gl.uniform1f(o.u.uT,tm);
  gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,FB.s.t);gl.uniform1i(o.u.uScene,0);gl.uniform2f(o.u.uRes,FB.W,FB.H);
  attr(o.a.aP,VL.vb,4,32,0);attr(o.a.aN,VL.vb,4,32,16);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,VL.f);gl.drawElements(gl.TRIANGLES,VL.cnt,gl.UNSIGNED_INT,0);off(o);
  gl.disable(gl.DEPTH_TEST);gl.blendFunc(gl.ONE,gl.ONE);                            // 亮片
