let pinch=0;
function mouseDragged(e){if(e&&e.target&&e.target.tagName&&e.target.tagName!=='CANVAS')return;yaw-=movedX*0.005;pitch=Math.max(-1.45,Math.min(1.45,pitch+movedY*0.005));return false}
function mouseWheel(e){dist=Math.max(600,Math.min(12000,dist*(1+e.delta*0.001)));return false}
function touchMoved(){if(touches.length===2){const d=Math.hypot(touches[0].x-touches[1].x,touches[0].y-touches[1].y);if(pinch)dist=Math.max(600,Math.min(12000,dist*pinch/d));pinch=d}else{pinch=0;yaw-=movedX*0.006;pitch=Math.max(-1.45,Math.min(1.45,pitch+movedY*0.006))}return false}
function touchEnded(){pinch=0}
let CV;function sizeCV(){const pd=Math.min(window.devicePixelRatio||1,1.5);CV.width=Math.round(innerWidth*pd);CV.height=Math.round(innerHeight*pd)}
function windowResized(){if(CV)sizeCV()}
